def shortest_over_20_sales(sales):
  l, r = 0, 0
  window_sum = 0
  cur_min = math.inf
  while True:
    must_grow = window_sum <= 20
    if must_grow:
      if r == len(sales):
        break
      window_sum += sales[r]
      r += 1
    else:
      cur_min = min(cur_min, r - l)
      window_sum -= sales[l]
      l += 1
  return cur_min if cur_min != math.inf else -1

