function shortestOver20Sales(sales) {
  let l = 0,
    r = 0;
  let windowSum = 0;
  let curMin = Infinity;
  while (true) {
    const mustGrow = windowSum <= 20;
    if (mustGrow) {
      if (r === sales.length) {
        break;
      }
      windowSum += sales[r];
      r++;
    } else {
      curMin = Math.min(curMin, r - l);
      windowSum -= sales[l];
      l++;
    }
  }
  return curMin !== Infinity ? curMin : -1;
}

