class ShortestOver20Sales {
  public int solve(int[] sales) {
    int l = 0, r = 0;
    int windowSum = 0;
    int curMin = Integer.MAX_VALUE;
    while (true) {
      boolean mustGrow = windowSum <= 20;
      if (mustGrow) {
        if (r == sales.length) {
          break;
        }
        windowSum += sales[r];
        r++;
      } else {
        curMin = Math.min(curMin, r - l);
        windowSum -= sales[l];
        l++;
      }
    }
    return curMin != Integer.MAX_VALUE ? curMin : -1;
  }
}

